<?php
namespace App\Http\Controllers;use App\Models\Category;use App\Models\Service;use Illuminate\Http\Request;
class ServiceController extends Controller{public function index(Request $r){$q=Service::with(['category','provider'])->where('is_active',true)->when($r->filled('q'),fn($x)=>$x->where(fn($w)=>$w->where('name','like','%'.$r->q.'%')->orWhere('description','like','%'.$r->q.'%')))->when($r->filled('category'),fn($x)=>$x->whereHas('category',fn($c)=>$c->where('slug',$r->category)))->latest()->paginate(12)->withQueryString();$categories=Category::where('is_active',true)->orderBy('name')->get();return view('services.index',compact('q','categories'));}public function show(Service $service){abort_unless($service->is_active,404);$service->load('category','provider','reviews.customer');return view('services.show',compact('service'));}}
